CREATE OR REPLACE FUNCTION public.owner_add_camera_unit_v1(p_unit_key text, p_unit_type text, p_camera_count integer, p_public_ip text, p_organization text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_actor public.profiles%rowtype; v_key text:=trim(coalesce(p_unit_key,'')); v_type text:=upper(trim(coalesce(p_unit_type,''))); v_reason text:=trim(coalesce(p_reason,'')); v_org text:=nullif(trim(coalesce(p_organization,'')),''); v_ip inet; i int; v_ids bigint[]:='{}'; v_id bigint; v_profile text; v_dtype text;
begin
 select * into v_actor from public.profiles where user_id=auth.uid() and active=true and archived_at is null;
 if not found or v_actor.role::text<>'owner' then raise exception 'Owner account required.'; end if;
 if v_key='' then raise exception 'Unit name/number is required.'; end if;
 if v_reason='' then raise exception 'Enter why this unit is being added.'; end if;
 if p_camera_count<1 or p_camera_count>8 then raise exception 'Camera count must be 1 through 8.'; end if;
 if exists(select 1 from public.camera_devices where lower(trim(coalesce(unit_key,'')))=lower(v_key)) then raise exception 'That unit already exists.'; end if;
 if nullif(trim(coalesce(p_public_ip,'')),'') is not null then v_ip:=trim(p_public_ip)::inet; end if;
 v_profile:=case when v_type like 'SNIPER%' then 'avigilon' when v_type like 'CAM V%' then 'avigilon' when v_type like 'HELIOS%' then 'helios' when v_type like 'SOLAR SPOTTER%' then 'solar_spotter' when v_type like 'SPOTTER%' then 'spotter' when v_type like 'RANGER%' then 'ranger' when v_type like 'RECON%' then 'reconeyez' else lower(replace(v_type,' ','_')) end;
 v_dtype:=case when v_type like 'SNIPER%' then 'Avigilon' when v_type like 'CAM V%' then 'Avigilon' else v_type end;
 for i in 1..p_camera_count loop
  insert into public.camera_devices(device_serial,device_name,device_model,device_type,device_owner,organization,public_ip,vigilant_status,source,monitoring_enabled,tech_check_unit_type,monitoring_profile,activation_state,activation_source,activated_at,unit_key,public_ip_source,public_ip_mapped_at,source_metadata)
  values('MANUAL-'||replace(v_key,' ','-')||'-CAM'||i,v_key||' Camera '||i,v_dtype,v_dtype,'Cameras Onsite',coalesce(v_org,'root'),v_ip,'Unknown','owner_manual',true,v_type,v_profile,'active','owner_manual',now(),v_key,case when v_ip is null then null else 'owner_manual' end,case when v_ip is null then null else now() end,jsonb_build_object('camera_number',i,'manual_inventory',true))
  returning id into v_id; v_ids:=array_append(v_ids,v_id);
 end loop;
 insert into public.camera_inventory_audit(actor_id,actor_name,action,unit_key,device_ids,after_state,reason) values(v_actor.user_id,coalesce(v_actor.full_name,v_actor.username,'Owner'),'ADD_UNIT',v_key,v_ids,jsonb_build_object('unit_type',v_type,'camera_count',p_camera_count,'public_ip',p_public_ip,'organization',coalesce(v_org,'root')),v_reason);
 return jsonb_build_object('ok',true,'unit_key',v_key,'added_devices',p_camera_count,'device_ids',v_ids);
end $function$

CREATE OR REPLACE FUNCTION public.owner_remove_camera_unit_v1(p_unit_key text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_actor public.profiles%rowtype; v_key text:=trim(coalesce(p_unit_key,'')); v_reason text:=trim(coalesce(p_reason,'')); v_ids bigint[]; v_before jsonb;
begin
 select * into v_actor from public.profiles where user_id=auth.uid() and active=true and archived_at is null;
 if not found or v_actor.role::text<>'owner' then raise exception 'Owner account required.'; end if;
 if v_key='' then raise exception 'Unit is required.'; end if;
 if v_reason='' then raise exception 'Enter why this unit is being removed.'; end if;
 select array_agg(id),jsonb_agg(to_jsonb(d)) into v_ids,v_before from public.camera_devices d where lower(trim(coalesce(unit_key,'')))=lower(v_key);
 if coalesce(array_length(v_ids,1),0)=0 then raise exception 'Unit not found.'; end if;
 insert into public.camera_inventory_audit(actor_id,actor_name,action,unit_key,device_ids,before_state,reason) values(v_actor.user_id,coalesce(v_actor.full_name,v_actor.username,'Owner'),'REMOVE_UNIT',v_key,v_ids,v_before,v_reason);
 delete from public.camera_devices where id=any(v_ids);
 return jsonb_build_object('ok',true,'unit_key',v_key,'removed_devices',array_length(v_ids,1));
end $function$

CREATE OR REPLACE FUNCTION public.owner_set_camera_unit_placement_v2(p_unit_key text, p_placement text, p_site_label text, p_street_address text, p_reason text, p_expected_audit_id bigint, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.profiles; v_key text:=btrim(coalesce(p_unit_key,'')); v_place text:=upper(btrim(coalesce(p_placement,''))); v_site text:=nullif(btrim(p_site_label),''); v_address text:=nullif(btrim(p_street_address),''); v_reason text:=btrim(coalesce(p_reason,'')); v_ids bigint[]; v_before jsonb; a public.camera_inventory_audit; v_latest bigint; v_id bigint; v_control uuid; v_payload jsonb; v_after jsonb;
begin
 select * into actor from public.profiles where user_id=auth.uid() and active=true and archived_at is null;
 if not found or not app_private.cos_verified_fleet_actor(actor.user_id) then raise exception 'Owner account required.' using errcode='42501'; end if;
 if length(v_key) not between 1 and 250 or v_place not in ('FIELD','SHOP') then raise exception 'Choose a camera unit and Field or Shop placement.' using errcode='22023'; end if;
 if length(v_reason) not between 1 and 4000 or p_request_id is null or (p_expected_audit_id is not null and p_expected_audit_id<1) then raise exception 'Reason, request identity and current placement revision are required.' using errcode='22023'; end if;
 if v_place='FIELD' and (coalesce(length(v_site),0) not between 1 and 250 or coalesce(length(v_address),0) not between 1 and 600
  or lower(v_site) in ('root','shop','shop/root','root/shop','shop / root','root / shop')
  or lower(v_address) in ('root','shop','shop/root','root/shop','shop / root','root / shop')) then
  raise exception 'Enter the current field site and installation street address.' using errcode='22023'; end if;
 if v_place='SHOP' and (v_site is not null or v_address is not null) then raise exception 'Shop moves do not replace a field site or address.' using errcode='22023'; end if;
 v_payload:=jsonb_build_object('unit_key',lower(v_key),'placement',v_place,'site_label',v_site,'street_address',v_address,'reason',v_reason,'expected_audit_id',p_expected_audit_id::text);
 -- This release gate also serializes the guarded, pre-first-use rollback.
 perform pg_advisory_xact_lock(702000,2);
 if to_regprocedure('public.owner_set_camera_unit_placement_v2(text,text,text,text,text,bigint,uuid)') is null then
  raise exception 'Placement controls changed. Reload the camera app.' using errcode='40001';
 end if;
 -- Request lock precedes unit lock to make replay safe even across different unit requests.
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,702002));
 select * into a from public.camera_inventory_audit where after_state->>'placement_contract'='COS_CAMERA_PLACEMENT_V2' and after_state->>'request_id'=p_request_id::text order by id desc limit 1;
 if found then
  if a.actor_id<>actor.user_id or a.after_state->'request_payload' is distinct from v_payload then raise exception 'Request identity was reused with different details.' using errcode='40001'; end if;
  return jsonb_build_object('ok',true,'unit_key',a.unit_key,'placement',a.after_state->>'placement','site_label',a.after_state->>'site_label','street_address',a.after_state->>'street_address','audit_id',a.id::text,'request_id',p_request_id,'devices_updated',cardinality(a.device_ids),'replayed',true);
 end if;
 perform pg_advisory_xact_lock(hashtextextended(lower(v_key),702001));
 -- Lock source rows before checking the latest audit, including against the existing v1 writer.
 perform id from public.camera_devices where lower(btrim(unit_key))=lower(v_key) order by id for update;
 select array_agg(id order by id),jsonb_agg(to_jsonb(d) order by id) into v_ids,v_before from public.camera_devices d where lower(btrim(unit_key))=lower(v_key);
 if coalesce(cardinality(v_ids),0)=0 then raise exception 'Camera unit not found.' using errcode='P0002'; end if;
 select id into v_latest from public.camera_inventory_audit where lower(btrim(unit_key))=lower(v_key) order by id desc limit 1;
 if v_latest is distinct from p_expected_audit_id then raise exception 'Placement changed. Reload the unit before saving.' using errcode='40001'; end if;
 select coalesce(after_state->>'control_id',after_state->>'request_id')::uuid into v_control from public.camera_inventory_audit
 where lower(btrim(unit_key))=lower(v_key) and after_state->>'placement_contract'='COS_CAMERA_PLACEMENT_V2' order by id asc limit 1;
 v_control:=coalesce(v_control,p_request_id);
 v_after:=jsonb_build_object('control_id',v_control,'placement_contract','COS_CAMERA_PLACEMENT_V2','placement',v_place,'site_label',v_site,'street_address',v_address,'request_id',p_request_id,'request_payload',v_payload,
  'organization',case when v_place='SHOP' then 'root' else v_site end,'activation_state',case when v_place='SHOP' then 'deactivated' else 'active' end);
 insert into public.camera_inventory_audit(actor_id,actor_name,action,unit_key,device_ids,before_state,after_state,reason)
 values(actor.user_id,coalesce(actor.full_name,actor.username,'Owner'),case when v_place='SHOP' then 'MOVE_TO_ROOT' else 'MOVE_TO_FIELD' end,v_key,v_ids,v_before,v_after,v_reason) returning id into v_id;
 update public.camera_devices set organization=v_after->>'organization',activation_state=v_after->>'activation_state',activation_source='owner_location_override_v2',
  activated_at=case when v_place='FIELD' then now() else activated_at end,updated_at=now() where id=any(v_ids);
 return jsonb_build_object('ok',true,'unit_key',v_key,'placement',v_place,'site_label',v_site,'street_address',v_address,'audit_id',v_id::text,'request_id',p_request_id,'devices_updated',cardinality(v_ids),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.set_camera_unit_connection_v2(p_device_id bigint, p_public_ip text, p_expected_revision bigint, p_expected_unit_etag text, p_ports integer[] DEFAULT NULL::integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.camera_devices%rowtype; selected public.camera_devices%rowtype; actor public.profiles%rowtype; address inet; ids bigint[]; affected integer; etag text;
begin
 select * into actor from public.profiles where user_id=auth.uid() and active=true and archived_at is null;
 if not found or not app_private.cos_verified_fleet_actor(auth.uid()) then raise exception 'Owner or IT account required';end if;
 select * into selected from public.camera_devices where id=p_device_id;
 if not found then raise exception 'Camera device not found';end if;
 if coalesce(trim(selected.unit_key),'') !~* '^(HELIOS|RANGER|SOLAR[ _-]*SPOTTER|SPOTTER|SS[ _-]*HYBRID|SNIPER( +[24])?|CAM *V|RECON( +(II|2))?|RII|RI) *[-#]? *[0-9]+([.][0-9]+)?$' then raise exception 'Unit family mapping required before changing this connection.';end if;
 -- Keep the exact family-qualified unit identity. Never match a bare number or IP.
 perform 1 from public.camera_devices where id=p_device_id or (coalesce(trim(selected.unit_key),'') ~* '^(HELIOS|RANGER|SOLAR[ _-]*SPOTTER|SPOTTER|SS[ _-]*HYBRID|SNIPER( +[24])?|CAM *V|RECON( +(II|2))?|RII|RI) *[-#]? *[0-9]+([.][0-9]+)?$' and lower(trim(unit_key))=lower(trim(selected.unit_key))) order by id for update;
 select * into d from public.camera_devices where id=p_device_id;
 select md5(jsonb_agg(jsonb_build_array(id,connection_revision,public_ip,expected_ports,unit_key) order by id)::text) into etag from public.camera_devices where id=p_device_id or (coalesce(trim(d.unit_key),'') ~* '^(HELIOS|RANGER|SOLAR[ _-]*SPOTTER|SPOTTER|SS[ _-]*HYBRID|SNIPER( +[24])?|CAM *V|RECON( +(II|2))?|RII|RI) *[-#]? *[0-9]+([.][0-9]+)?$' and lower(trim(unit_key))=lower(trim(d.unit_key)));
 if etag is distinct from p_expected_unit_etag then raise exception 'Unit connection changed. Reload before saving.';end if;
 if d.connection_revision is distinct from p_expected_revision or d.unit_key is distinct from selected.unit_key then raise exception 'Connection changed. Reload before saving.';end if;
 begin address:=trim(p_public_ip)::inet;exception when others then raise exception 'Enter a valid public IPv4 address';end;
 if address is null or family(address)<>4 or masklen(address)<>32 or address<<any(array['0.0.0.0/8','10.0.0.0/8','100.64.0.0/10','127.0.0.0/8','169.254.0.0/16','172.16.0.0/12','192.0.0.0/24','192.0.2.0/24','192.168.0.0/16','198.18.0.0/15','198.51.100.0/24','203.0.113.0/24','224.0.0.0/4','240.0.0.0/4']::inet[]) then raise exception 'Enter a public IPv4 host address';end if;
 if p_ports is not null and (cardinality(p_ports)>32 or cardinality(p_ports)=0 or array_position(p_ports,null) is not null or exists(select 1 from unnest(p_ports) p where p<1 or p>65535)) then raise exception 'Enter 1 to 32 valid service ports';end if;
 select array_agg(id order by id) into ids from public.camera_devices where id=p_device_id or (coalesce(trim(d.unit_key),'') ~* '^(HELIOS|RANGER|SOLAR[ _-]*SPOTTER|SPOTTER|SS[ _-]*HYBRID|SNIPER( +[24])?|CAM *V|RECON( +(II|2))?|RII|RI) *[-#]? *[0-9]+([.][0-9]+)?$' and lower(trim(unit_key))=lower(trim(d.unit_key)));
 if exists(select 1 from public.camera_devices where id=any(ids) and public_ip is distinct from d.public_ip) then raise exception 'This unit has conflicting saved endpoints. Resolve the device mapping first.';end if;
 update public.camera_devices set public_ip=address,expected_ports=case when id=p_device_id and p_ports is not null then array(select distinct p from unnest(p_ports) p order by p) else expected_ports end,
 public_ip_source='owner_manual',public_ip_mapped_at=now(),updated_at=now() where id=any(ids);
 get diagnostics affected=row_count;
 update public.equipment_master set tracker_public_ip=address,updated_at=now() where coalesce(trim(d.unit_key),'') ~* '^(HELIOS|RANGER|SOLAR[ _-]*SPOTTER|SPOTTER|SS[ _-]*HYBRID|SNIPER( +[24])?|CAM *V|RECON( +(II|2))?|RII|RI) *[-#]? *[0-9]+([.][0-9]+)?$' and lower(trim(source_label))=lower(trim(d.unit_key));
 select * into d from public.camera_devices where id=p_device_id;
 select md5(jsonb_agg(jsonb_build_array(id,connection_revision,public_ip,expected_ports,unit_key) order by id)::text) into etag from public.camera_devices where id=any(ids);
 return jsonb_build_object('ok',true,'device_id',d.id,'unit_etag',etag,'unit_key',d.unit_key,'public_ip',host(d.public_ip),'expected_ports',coalesce(d.expected_ports,'{}'::integer[]),'connection_revision',d.connection_revision,'camera_rows_updated',affected);
end $function$

