CREATE OR REPLACE FUNCTION public.camera_connection_invalidate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if row(new.public_ip,new.expected_ports,new.monitoring_profile,new.unit_key,new.monitoring_enabled)
     is distinct from row(old.public_ip,old.expected_ports,old.monitoring_profile,old.unit_key,old.monitoring_enabled) then
    insert into public.camera_health_history(camera_device_id,status,check_source,observed_at,detail)
    values(old.id,'unknown','saved_connection_changed',clock_timestamp(),jsonb_build_object(
      'actor',auth.uid(),'previous_ip',host(old.public_ip),'new_ip',host(new.public_ip),
      'previous_ports',old.expected_ports,'new_ports',new.expected_ports,
      'previous_revision',old.connection_revision,'new_revision',old.connection_revision+1,
      'previous_last_success',old.last_probe_online_at));
    new.connection_revision:=old.connection_revision+1;
    new.last_probe_online_at:=null;
    if lower(coalesce(new.monitoring_profile,'')) in ('sniper','camv') then new.last_health_checked_at:=null; end if;
    update public.camera_health_current set port_status='{}',ip_reachable=null,
      overall_status=case when lower(coalesce(new.monitoring_profile,'')) in ('sniper','camv') then 'unknown' else overall_status end,
      checked_at=case when lower(coalesce(new.monitoring_profile,'')) in ('sniper','camv') then null else checked_at end,
      consecutive_failures=case when lower(coalesce(new.monitoring_profile,'')) in ('sniper','camv') then 0 else consecutive_failures end,
      confirmed_outage=case when lower(coalesce(new.monitoring_profile,'')) in ('sniper','camv') then false else confirmed_outage end,
      confirmation_reason=case when lower(coalesce(new.monitoring_profile,'')) in ('sniper','camv') then null else confirmation_reason end,
      detail=case when lower(coalesce(new.monitoring_profile,'')) in ('sniper','camv') then 'Saved connection changed; awaiting a check of the new endpoint.' else detail end
    where camera_device_id=new.id;
  else
    new.connection_revision:=old.connection_revision;
    -- Older publishers cannot refresh a new endpoint's last-success timestamp.
    if new.last_probe_online_at is distinct from old.last_probe_online_at
       and current_setting('cos.connection_publish_device',true) is distinct from new.id::text then
      new.last_probe_online_at:=old.last_probe_online_at;
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_camera_owner_placement_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.camera_inventory_audit;
begin
 select * into a from public.camera_inventory_audit where lower(btrim(unit_key))=lower(btrim(new.unit_key)) order by id desc limit 1;
 if a.after_state->>'placement_contract'='COS_CAMERA_PLACEMENT_V2' and new.id=any(a.device_ids) then
  new.organization:=a.after_state->>'organization';new.activation_state:=a.after_state->>'activation_state';new.activation_source:='owner_location_override_v2';
 elsif new.activation_source='owner_location_override_v2' then
  new.activation_source:=null;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.cos_camera_identity_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and row(old.id,old.source,old.device_type,old.external_device_id,old.device_serial,old.unit_key)
  is not distinct from row(new.id,new.source,new.device_type,new.external_device_id,new.device_serial,new.unit_key) then return new; end if;
 if tg_op in ('UPDATE','DELETE') and old.unit_key is not null then
  insert into app_private.cos_camera_identity_events(unit_key,camera_device_id) values(old.unit_key,old.id);
 end if;
 if tg_op='INSERT' or (tg_op='UPDATE' and new.unit_key is distinct from old.unit_key) then
  if new.unit_key is not null then insert into app_private.cos_camera_identity_events(unit_key,camera_device_id) values(new.unit_key,new.id); end if;
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.cos_geocode_enqueue_new_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_key text; v_address text;
begin
 if new.action::text<>'MOVE_TO_FIELD' or new.after_state->>'placement_contract' is distinct from 'COS_CAMERA_PLACEMENT_V2'
  or new.after_state->>'placement' is distinct from 'FIELD' then return new; end if;
 if not app_private.cos_verified_fleet_actor(new.actor_id) then return new; end if;
 v_key:=app_private.cos_geocode_unit_key(new.unit_key);
 v_address:=app_private.cos_geocode_normalize_address(new.after_state->>'street_address');
 if v_key is null or v_address is null or length(v_key)>250 or length(v_address) not between 1 and 600 then return new; end if;
 insert into app_private.cos_field_geocode_cache(organization_id,audit_id,unit_key,address,address_sha256)
 values('ece6d2a2-fd19-4cc7-b56a-2fa004a6d8f5',new.id::text,v_key,v_address,encode(sha256(convert_to(v_address,'UTF8')),'hex'))
 on conflict (organization_id,audit_id) do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.ensure_service_truck_baseline_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.active=true and new.role::text='service' then
    perform public.ensure_service_truck_baseline_v1(new.user_id);
  end if;
  return new;
end;
$function$
